WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (21::BIGINT, 'Profe si está leyendo esto, mi emprendedor era fake'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Muchos exámenes']::TEXT[], '2026-10-04T00:00:00+00:00'::TIMESTAMPTZ, 'ce2efe6b309a9a27f8aebaac3bcfeccba686d6ce3c2abc1a7e9917bff8eac54d'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Ni idea de las otras calificaciones, pero ella es super amigable y ayuda si es necesario, el curso es aburrido de por sí, eso sí, si usa todo el rato de la clase y se hacen pesadas, pero muchas de estas son para hacer trabajos, con que tenga un grupo que trabaje el curso se pasa bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos proyectos grupales']::TEXT[], '2026-08-04T00:00:00+00:00'::TIMESTAMPTZ, '2486dca96809b43cc1453cb1af8846f26f473946f4fb2170a7a2b0cb09e1b791'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Solo vagos acá, sinceramente no se crea lo que dicen los demás, la profesora es excelente en lo que hace, pero si usted transpira Chat GPT y no hace nada por su vida lo revienta, es el tipo de profesor que uno espera en una universidad del nivel del TEC, ella si lo pone a bretear a uno.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2025-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'aa47ae01622aeea865c675882fff8148f750938aa336b72206c6208e476dd486'::TEXT, ARRAY[2442]::BIGINT[]),
    (21::BIGINT, 'La profe se toma muy encerio el curso pero si logras juntarte con un grupo que si trabaje la carga de trabajo no se siente tanto, si es demasiado vaga para calificar, las calificaciones de exámenes, tareas, proyectos, etc las entrega prácticamente el día antes de la entrega de actas.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'ad89d3e772301e4fdbd756af6da3e3d359e83dd9abb7b34a84639cb531b85482'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'La mae es dema irritante. Se hace la inspiracional como si sus clases nos fueran a cambiar la vida pero uno no aprende nada. La carga de trabajo es bastante alta, siempre se hacen guías y la asistencia obligatoria. Si solo quiere pasar, no matricule con ella.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-06T00:00:00+00:00'::TIMESTAMPTZ, '1e942e9c6ad96be82621a2ded9ca2c2f561bb2f5df8d59768b00416eb86294d6'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Fatal es la única palabra disponible para calificar a esta profesora.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2025-10-14T00:00:00+00:00'::TIMESTAMPTZ, 'cb9892024b70e513aa8a228134c7316b8f4b9891b582263eb9e6b3b5680724d1'::TEXT, ARRAY[2442]::BIGINT[]),
    (21::BIGINT, 'Se toma un curso que es obligatorio como si nos fuera a cambiar la vida. Se hace la muy inspiracional y eso hace que las clases sean demasiado poco realistas y aburridas. Hace actividades excesivas y pretende que sea el curso más importante'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-09-25T00:00:00+00:00'::TIMESTAMPTZ, 'e774e426623e8e1f43eaeebe0be5cfa9f601949bd78eb4a89e9558566702c590'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Es el típico curso de la carrera que la profe cree que es importantísimo pero realmente no te está enseñando nada útil. Es ver puros videos de youtube de historias de resiliencia y aprenderse los tipos de emprendedores. Una clase se fue temprano, nos dejó con un profe y nos dejó ahí sentados por 2h'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-09-20T00:00:00+00:00'::TIMESTAMPTZ, '7d26f09e49d890975f5b1cc388f7a09f255986cc6b954bd58f96fd031a31824d'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'La profe hace que el curso sea mucho más llevadero y de verdad se nota el amor en sus clases. Busque una persona emprendedora para los exámenes y las evaluaciones son relativamente sencillas. La mejor de la escuela.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-01-21T00:00:00+00:00'::TIMESTAMPTZ, '219ca742773ac05cf1c4f74fb48278c4df02d5aa692c9d77972d11970fd51e94'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, '30% el proyecto, 25% Guías grupales, 15% Tareas individuales y 30% dos Retos (Exámenes). La profe entrega notas el día antes de actas, da chance de corregir los avances del proyecto y responde rápido por correo. Busque un buen equipo, consulté y contacte con una persona emprendedora desde el inicio.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'e215e8a8531cff51f599a949355ee073db45e028cfaeca2316254a09503b9cef'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Si quieren llevar un curso malo y de alta dificultad, esta es la clase para ustedes. Si no me creen, matriculen con ella, para que conozcan que el infierno si existe...'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2023-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'b64e517be8fd44c6420e29285ea9ff030d74022f6a64a6ba103e91cb03da492e'::TEXT, ARRAY[2442]::BIGINT[]),
    (21::BIGINT, 'Realmente las clases se hacen muy aburridas, no es muy dificil pero requiere hacer muchos trabajos en grupo.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas']::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, '4a72f229c07ef2c359386a32446a958fa117f36c35f3f9c1822d31c70f0085f8'::TEXT, ARRAY[2442]::BIGINT[]),
    (21::BIGINT, 'Instrucciones poco claras en muchas ocasiones, califica todo hasta lo último, las clases no son tan aburridas y es un amor de persona. La recomiendo si quiere pasar sin complicarse mucho'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-18T00:00:00+00:00'::TIMESTAMPTZ, '7cd03a4c379a6514ebd39eff4e77c0b4432b8e98cf8fa4cc11c09fe2af8aec43'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Las clases son muy cortas con la justificación de que hay mucho que hacer fuera de la clase. La profesora explica muy poco y no se le entiende, muchas veces deja vídeos explicativos y responde solo los días que da clases los correos entonces se vuelve difícil la comunicación. No motiva a emprender.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c2942943b3404b74bf5a8a7d57f7af4b6a329b3b4dd250dd5569da33e7b3498d'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Clases virtuales aburridas. La presentación de la materia no es clara. Deja demasiados trabajos/tareas/evaluaciones. Responde los correos tarde o no los responde del todo. Califica hasta final de semestre las evaluaciones. Desordenada. Sube el material de la clase muy tarde.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '46ccb0bc794a0b536b019e50ebf81353fb858599ad8301569e67959559dd044c'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Las clases son muy aburridas y entrega notas tardísimo, pero es una persona muy amable.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '858dd35414986cde44c636ee0fec1c139268984bc2ffdde9c04ba3535922b28b'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'La profe es agradable y buena nota pero las clases super largas y aburridas. Deja una cantidad de trabajos excesiva, sobre todo si se estan lle'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-12-09T00:00:00+00:00'::TIMESTAMPTZ, '400391430bed306964b769653d4a54e9c279386c2385b6bb0c9e7b019bd54248'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Las clases virtuales fueron aburrida y poco claras. Se atrasan mucho en enviar y calificar las notas y tarda mucho en responder los correos.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '8f911a0b4b5d1f790280e3786af0465c3c7b83262ad379dcb7fb9c2ddedab5be'::TEXT, ARRAY[2442]::BIGINT[]),
    (21::BIGINT, 'Las clases son un poco aburridas y en ocaciones dura mucho para entregar las cosas calificadas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'b464498945283a00452f363976a9a6d784040f170cce2967943b3a0ee89c606c'::TEXT, ARRAY[2463]::BIGINT[]),
    (21::BIGINT, 'Muy ordenada y exámenes son fáciles/dinámicos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, 'd9e6d948e9bfac3dbfe72808bf5fc79baf2c960e4d94822779dd54a7723e951b'::TEXT, ARRAY[2463]::BIGINT[]),
    (21::BIGINT, 'Se toma el curso muy en serio, hace las clases excesivamente largas y aburridas, por más que trata de hacer actividades. Va a pasar, fácil, pero hay profes más tranquipiolis. Deja la lista como para el último minuto :))))'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '21f47cf8f2618d31dc38bd031bd73804dca2a5ef23f8315900a9fca7c16f9103'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Es buena profe y muy agradable, las clases son aburridas, pero ella hace que se aliviane la carga, para que el curso no quite mucho tiempo extraclase'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'cbc7a4ba3c3e718183b2de7f24d0049fd0387365a9e596069fb907db307def18'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'En general es una profesora muy buena. Prepara muy bien las clases con presentaciones, hace muy buenas dinámicas para que la clase no sea tan aburrida. Revisa el trabajo final con mucha paciencia, trató siempre que ayudar a los estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, '2e960174095dd9ef5c4d91a30e03b13c243c387cf9f3126bed654a85c856d147'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Exelente profe, aunque los trabajos sean tediosos, la profe los hace llevaderos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2018-11-15T00:00:00+00:00'::TIMESTAMPTZ, '5d20b3cc3625538442d339e3881bd8c9f0225dc8b20e39ee4642f2947d41322a'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'El curso es aburrido pero la profe es buena nota, califica justamente, hay que llevar los trabajos al día y no faltar a clases(No olvide las lecturas)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-31T00:00:00+00:00'::TIMESTAMPTZ, 'd2a54d9a6bba56c6a0b1b0980f16ec04fa9c3d0dacc099ff149050ab55d952e2'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'DEJA DEMASIADOS TRABAJOS EN COMPARACIÓN CON LOS OTROS PROFES OMG'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-08-29T00:00:00+00:00'::TIMESTAMPTZ, '697b6b3ba629c9cbcef477075e69ad31a43af1ddb86a064a2e385b4b93074a3c'::TEXT, ARRAY[965]::BIGINT[]),
    (21::BIGINT, 'Excelente profesora, es muy pura vida y dinámica. Las clases no son aburridas y se aprende un montón. No deja muchos trabajo y son fáciles.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, '9dcede7f86480d7fe80a8e3ce698e8fad0245938fbe455ca5ebbbaebc71ad1ac'::TEXT, ARRAY[965]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
